```css
.alert-banner {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--cresyl);
  border-left-width: 4px;
  border-radius: 12px;
  background: var(--cresyl-wash);
  color: var(--ink);
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
}

.alert-banner__icon {
  flex: none;
  width: 1.25em;
  height: 1.25em;
  color: var(--cresyl);
}

.alert-banner__message {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
}

.alert-banner__retry {
  flex: none;
  font: inherit;
  font-weight: 600;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--ink);
  border-radius: 999px;
  padding: 0.375rem 0.875rem;
  cursor: pointer;
  transition: background-color 150ms ease;
}

.alert-banner__retry:hover {
  background: var(--myelin-wash);
}

:root[data-motion="reduce"] .alert-banner__retry {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .alert-banner__retry {
    transition: none;
  }
}
